// DaftarNama.java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class DaftarNama {
    private List<String> daftar = new ArrayList<>();

    public boolean tambah(String nama) {
        for (String n : daftar) {
            if (n.equalsIgnoreCase(nama)) {
                return false;
            }
        }
        daftar.add(nama);
        return true;
    }

    public boolean hapus(String nama) {
        return daftar.remove(nama);
    }

    public int jumlah() {
        return daftar.size();
    }

    public List<String> urut() {
        List<String> salinan = new ArrayList<>(daftar);
        Collections.sort(salinan, String.CASE_INSENSITIVE_ORDER);
        return salinan;
    }

    public List<String> cariAwalan(String awalan) {
        List<String> hasil = new ArrayList<>();
        for (String n : daftar) {
            if (n.toLowerCase().startsWith(awalan.toLowerCase())) {
                hasil.add(n);
            }
        }
        return hasil;
    }
}

