// Frekuensi.java
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

public class Frekuensi {
    public static Map<String, Integer> hitung(String kalimat) {
        Map<String, Integer> hasil = new TreeMap<>();
        for (String kata : kalimat.trim().toLowerCase().split("\\s+")) {
            if (!kata.isEmpty()) {
                hasil.merge(kata, 1, Integer::sum);
            }
        }
        return hasil;
    }

    public static Set<String> unik(String[] kata) {
        Set<String> hasil = new LinkedHashSet<>();
        for (String k : kata) {
            hasil.add(k);
        }
        return hasil;
    }
}
